insert into banglog_plus.legal_sources(id,title,institution,url) values('civil-623','민법 제623조 · 임대인의 의무','국가법령정보센터 / 법무부','https://www.law.go.kr/LSW/lsSideInfoP.do?docCls=jo&joBrNo=00&joNo=0623&lsiSeq=284415&urlMode=lsScJoRltInfoR') on conflict do nothing;
insert into banglog_plus.legal_source_versions(source_id,version,location,checked_at,effective_date,technical_status,human_legal_review,use_scope,metadata) values('civil-623','2026-03-17.official-2026-11-10.v1','제623조','2026-11-10','2026-03-17','verified','pending','general','{"id": "civil-623", "version": "2026-03-17.official-2026-11-10.v1", "title": "민법 제623조 · 임대인의 의무", "institution": "국가법령정보센터 / 법무부", "url": "https://www.law.go.kr/LSW/lsSideInfoP.do?docCls=jo&joBrNo=00&joNo=0623&lsiSeq=284415&urlMode=lsScJoRltInfoR", "location": "제623조", "checkedAt": "2026-11-10", "effectiveDate": "2026-03-17", "technicalStatus": "verified", "humanLegalReview": "pending", "use": "general", "reviewBasis": "official_statute", "scope": "수리 요청의 일반 원칙만 안내. 사소한 수리·특약·사용상 과실·원인을 별도로 확인하며 전액 배상이나 책임 비율을 도출하지 않음.", "issues": ["mold", "leak", "boiler", "surface", "drain", "fixture"], "reviewEvidence": {"crossCheckUrl": "https://easylaw.go.kr/CSP/CnpClsMainBtr.laf?ccfNo=4&cciNo=2&cnpClsNo=3&csmSeq=1171&menuType=cnpcls&popMenu=ov", "permissionEvidenceUrl": "https://www.law.go.kr/lsLinkProc.do?joNo=000700&lsClsCd=L&lsNm=%EC%A0%80%EC%9E%91%EA%B6%8C%EB%B2%95&mode=11", "originalSha256": "d6475b5032a8ecc401344a38aae67bfe3e4786983a0e22413caac85f9ca3c0a4", "reviewerType": "ai_source_comparison"}}'::jsonb) on conflict do nothing;
insert into banglog_plus.knowledge_chunks(id,dataset_version,source_id,source_version,claim_id,claim,content,issues,keywords,observations) values('official-civil-623','official-statutes-2026-11-10.v1','civil-623','2026-03-17.official-2026-11-10.v1','official-623','임대인에게 사용에 지장이 있는 증상과 점검·수리를 요청할 수 있어요. 이 조문만으로 원인이나 모든 비용의 부담을 확정하지 않아요.','[공식 조문 원문] 임대인은 목적물을 임차인에게 인도하고 계약존속중 그 사용, 수익에 필요한 상태를 유지하게 할 의무를 부담한다.
insert into banglog_plus.source_permissions(source_id,source_version,external_llm_allowed,permission_evidence_url,reviewed_by,checked_at,expires_at) values('civil-623','2026-03-17.official-2026-11-10.v1',true,'https://www.law.go.kr/lsLinkProc.do?joNo=000700&lsClsCd=L&lsNm=%EC%A0%80%EC%9E%91%EA%B6%8C%EB%B2%95&mode=11','codex:official-statute-comparison-not-human-legal-review','2026-11-10T00:00:00Z','2027-02-10T00:00:00Z') on conflict do nothing;
insert into banglog_plus.legal_sources(id,title,institution,url) values('civil-634','민법 제634조 · 임차인의 통지의무','국가법령정보센터 / 법무부','https://www.law.go.kr/LSW/lsSideInfoP.do?docCls=jo&joBrNo=00&joNo=0634&lsiSeq=284415&urlMode=lsScJoRltInfoR') on conflict do nothing;
insert into banglog_plus.legal_source_versions(source_id,version,location,checked_at,effective_date,technical_status,human_legal_review,use_scope,metadata) values('civil-634','2026-03-17.official-2026-11-10.v1','제634조','2026-11-10','2026-03-17','verified','pending','general','{"id": "civil-634", "version": "2026-03-17.official-2026-11-10.v1", "title": "민법 제634조 · 임차인의 통지의무", "institution": "국가법령정보센터 / 법무부", "url": "https://www.law.go.kr/LSW/lsSideInfoP.do?docCls=jo&joBrNo=00&joNo=0634&lsiSeq=284415&urlMode=lsScJoRltInfoR", "location": "제634조", "checkedAt": "2026-11-10", "effectiveDate": "2026-03-17", "technicalStatus": "verified", "humanLegalReview": "pending", "use": "general", "reviewBasis": "official_statute", "scope": "통지와 기록 보존의 일반 안내. 관리 담당자 연락이 임대인 통지를 항상 대체한다고 보지 않음. 늦게 알렸다고 모든 권리 상실·전액 과실로 단정하지 않음.", "issues": ["mold", "leak", "boiler", "surface", "drain", "fixture"], "reviewEvidence": {"crossCheckUrl": "https://easylaw.go.kr/CSP/CnpClsMainBtr.laf?ccfNo=4&cciNo=2&cnpClsNo=3&csmSeq=1171&menuType=cnpcls&popMenu=ov", "permissionEvidenceUrl": "https://www.law.go.kr/lsLinkProc.do?joNo=000700&lsClsCd=L&lsNm=%EC%A0%80%EC%9E%91%EA%B6%8C%EB%B2%95&mode=11", "originalSha256": "e1bd67302045c8fc7e7130705a2e24d99d944ce7203b001eae0e5f0efd85eaf7", "reviewerType": "ai_source_comparison"}}'::jsonb) on conflict do nothing;
insert into banglog_plus.knowledge_chunks(id,dataset_version,source_id,source_version,claim_id,claim,content,issues,keywords,observations) values('official-civil-634','official-statutes-2026-11-10.v1','civil-634','2026-03-17.official-2026-11-10.v1','official-634','수리가 필요한 사실을 알게 되면 임대인에게 지체 없이 알려야 해요. 임대인이 이미 알고 있는 경우는 예외이며, 발견 시점과 연락 내용을 남겨 두면 상황 확인에 도움이 돼요.','[공식 조문 원문] 임차물의 수리를 요하거나 임차물에 대하여 권리를 주장하는 자가 있는 때에는 임차인은 지체없이 임대인에게 이를 통지하여야 한다. 그러나 임대인이 이미 이를 안 때에는 그러하지 아니하다.
