insert into banglog_plus.legal_source_versions(source_id,version,location,checked_at,effective_date,technical_status,human_legal_review,use_scope,metadata) values('civil-626','2026-03-17.official-2026-11-10.v1','제626조 제1항','2026-11-10','2026-03-17','verified','pending','general','{"id": "civil-626", "version": "2026-03-17.official-2026-11-10.v1", "title": "민법 제626조 · 임차인의 상환청구권", "institution": "국가법령정보센터 / 법무부", "url": "https://www.law.go.kr/LSW/lsSideInfoP.do?docCls=jo&joBrNo=00&joNo=0626&lsiSeq=284415&urlMode=lsScJoRltInfoR", "location": "제626조 제1항", "checkedAt": "2026-11-10", "effectiveDate": "2026-03-17", "technicalStatus": "verified", "humanLegalReview": "pending", "use": "general", "reviewBasis": "official_statute", "scope": "제1항 필요비에 한정. 모든 수리비 반환 보장, 먼저 결제 권유, 임의 월세 공제 금지. 비용 필요성·원인·특약·증빙 확인과 협의 안내에만 사용.", "issues": ["mold", "leak", "boiler", "surface", "drain", "fixture"], "reviewEvidence": {"crossCheckUrl": "https://easylaw.go.kr/CSP/CnpClsMainBtr.laf?ccfNo=4&cciNo=2&cnpClsNo=3&csmSeq=1171&menuType=cnpcls&popMenu=ov", "permissionEvidenceUrl": "https://www.law.go.kr/lsLinkProc.do?joNo=000700&lsClsCd=L&lsNm=%EC%A0%80%EC%9E%91%EA%B6%8C%EB%B2%95&mode=11", "originalSha256": "8e93d9fde597c60d0cd13d577476275e0252fa5a000bb4e45fde32439a0aa7e1", "reviewerType": "ai_source_comparison"}}'::jsonb) on conflict do nothing;
insert into banglog_plus.knowledge_chunks(id,dataset_version,source_id,source_version,claim_id,claim,content,issues,keywords,observations) values('official-civil-626','official-statutes-2026-11-10.v1','civil-626','2026-03-17.official-2026-11-10.v1','official-626','임차물이 보존되는 데 필요한 비용을 지출했다면 상환을 청구할 수 있다는 규정이 있어요. 실제로 필요비에 해당하는지와 계약 내용·지출 증빙을 확인해야 해요.','[공식 조문 원문] ①임차인이 임차물의 보존에 관한 필요비를 지출한 때에는 임대인에 대하여 그 상환을 청구할 수 있다.
